import sys
from itertools import groupby

def main():
    s = sys.stdin.read().split()[0]
    while True:
        out = []
        changed = False
        for d, g in groupby(s):
            k = len(list(g))
            if k > 1:
                out.append(str(int(d) * k))
                changed = True
            else:
                out.append(d)
        if not changed:
            break
        s = ''.join(out)
    print(s)

main()

